window.__OPENSTAX_PHYSICS__[12] = {"schemaVersion":"4.0.0-physics","generatedAt":"2026-11-27T01:44:27.351Z","number":12,"code":"ch12","slug":"thermodynamics","title":"Thermodynamics","titleVi":"Nhiệt Động Lực Học (Thermodynamics)","sections":[{"uid":"hsphys.ch12.sec00","moduleId":"m54300","number":"12.0","slug":"introduction","title":"Introduction","isIntroduction":true,"learningObjectives":[],"bilingualGuide":null,"keyEquations":[],"subsections":[{"uid":"hsphys.ch12.sec00.sub01","title":"Chapter Introduction","summaryVi":"Tổng quan mở đầu chương: Nhiệt Động Lực Học (Thermodynamics) — giới thiệu hiện tượng thực tế và các câu hỏi nền tảng trước khi đi vào định luật chi tiết.","paragraphs":["Energy can be transferred to or from a system, either through a temperature difference between it and another system (i.e., by heat) or by exerting a force through a distance (work). In these ways, energy can be converted into other forms of energy in other systems. For example, a car engine burns fuel for heat transfer into a gas. Work is done by the gas as it exerts a force through a distance by pushing a piston outward. This work converts the energy into a variety of other forms—into an increase in the car’s kinetic or gravitational potential energy; into electrical energy to run the spark plugs, radio, and lights; and back into stored energy in the car’s battery. But most of the thermal energy transferred by heat from the fuel burning in the engine does not do work on the gas. Instead, much of this energy is released into the surroundings at lower temperature (i.e., lost through heat), which is quite inefficient. Car engines are only about 25 to 30 percent efficient. This inefficiency leads to increased fuel costs, so there is great interest in improving fuel efficiency. However, it is common knowledge that modern gasoline engines cannot be made much more efficient. The same is true about the conversion to electrical energy in large power stations, whether they are coal, oil, natural gas, or nuclear powered. Why is this the case?","The answer lies in the nature of heat. Basic physical laws govern how heat transfer for doing work takes place and limit the maximum possible efficiency of the process. This chapter will explore these laws as well their applications to everyday machines. These topics are part of thermodynamics —the study of heat and its relationship to doing work."],"figures":[{"sourceId":"fs-id1167066832216","filename":"CNX_HSPhysics_12_00_Train-d3d5.jpg","relativePath":"media/CNX_HSPhysics_12_00_Train-d3d5.jpg","alt":"Smoke rises from the stack of a train travelling through the mountains"}],"tables":[]}],"workedExamples":[],"snapLabs":[],"tipsAndFeatures":[],"summaryPoints":[],"glossary":[],"assessments":[],"stats":{"learningObjectiveCount":0,"keyEquationCount":0,"subsectionCount":1,"workedExampleCount":0,"snapLabCount":0,"glossaryCount":0,"assessmentCount":0}},{"uid":"hsphys.ch12.sec01","moduleId":"m54302","number":"12.1","slug":"zeroth-law-of-thermodynamics-thermal-equilibrium","title":"Zeroth Law of Thermodynamics: Thermal Equilibrium","isIntroduction":false,"learningObjectives":["Explain the zeroth law of thermodynamics"],"bilingualGuide":{"notebookSummaryVi":"Trạng thái cân bằng nhiệt (Thermal Equilibrium) và Nguyên lý thứ 0 của Nhiệt động lực học.","wordProblemCues":[{"phraseEn":"thermal equilibrium","meaningVi":"Cân bằng nhiệt (cùng nhiệt độ)","mathNotation":"T₁ = T₂"}],"commonTrapsVi":["Nhiệt kế đo nhiệt độ của chính nó sau khi đạt cân bằng nhiệt với vật cần đo!"]},"keyEquations":[],"subsections":[],"workedExamples":[],"snapLabs":[],"tipsAndFeatures":[{"uid":"hsphys.ch12.sec01.feat01","type":"tip","title":"Tips for Success","text":"The zeroth law of thermodynamics is very similar to the transitive property of equality in mathematics: If a = b and b = c, then a = c.","images":[]},{"uid":"hsphys.ch12.sec01.feat02","type":"physics-in-action","title":"Thermodynamics Engineer","text":"Thermodynamics engineers apply the principles of thermodynamics to mechanical systems so as to create or test products that rely on the interactions between heat, work, pressure, temperature, and volume. This type of work typically takes place in the aerospace industry, chemical manufacturing companies, industrial manufacturing plants, power plants (Figure 12.1), engine manufacturers, or electronics companies.\nAn engineer makes a site visit to the Baghdad South power plant.\nThe need for energy creates quite a bit of demand for thermodynamics engineers, because both traditional energy companies and alternative ( green ) energy startups rely on interactions between heat and work and so require the expertise of thermodynamics engineers. Traditional energy companies use mainly nuclear energy and energy from burning fossil fuels, such as coal. Alternative energy is finding new ways to harness renewable and, often, more readily available energy sources, such as solar, water, wind, and bio-energy.\nA thermodynamics engineer in the energy industry can find the most efficient way to turn the burning of a biofuel or fossil fuel into energy, store that energy for times when it’s needed most, or figure out how to best deliver that energy from where it’s produced to where it’s used: in homes, factories, and businesses. Additionally, he or she might also design pollution-control equipment to remove harmful pollutants from the smoke produced as a by-product of burning fuel. For example, a thermodynamics engineer may develop a way to remove mercury from burning coal in a coal-fired power plant.\nThermodynamics engineering is an expanding field, where employment opportunities are expected to grow by as much as 27 percent between 2012 and 2022, according to the U.S. Bureau of Labor Statistics. To become a thermodynamics engineer, you must have a college degree in chemical engineering, mechanical engineering, environmental engineering, aerospace engineering, civil engineering, or biological engineering (depending on which type of career you wish to pursue), with coursework in physics and physical chemistry that focuses on thermodynamics.\nWhat would be an example of something a thermodynamics engineer would do in the aeronautics industry?\nTest the fuel efficiency of a jet engine\nTest the functioning of landing gear\nTest the functioning of a lift control device\nTest the autopilot functions","images":[{"sourceId":"fs-id1167066944808","filename":"CNX_HSPhysics_12_01_engineer.jpg","relativePath":"media/CNX_HSPhysics_12_01_engineer.jpg","alt":"A woman wearing a hardhat walks between steaming pipes."}]}],"summaryPoints":["Systems are in thermal equilibrium when they have the same temperature.","Thermal equilibrium occurs when two bodies are in contact with each other and can freely exchange energy.","The zeroth law of thermodynamics states that when two systems, A and B, are in thermal equilibrium with each other, and B is in thermal equilibrium with a third system, C, then A is also in thermal equilibrium with C."],"glossary":[{"term":"thermal equilibrium","termVi":"Trạng thái cân bằng nhiệt","ipa":"/ˈθɜː.məl ˌiː.kwɪˈlɪb.ri.əm/","definition":"condition in which heat no longer transfers energy between two objects that are in contact; the two objects have the same temperature","definitionVi":"Trạng thái khi hai vật tiếp xúc nhau có cùng nhiệt độ và không còn trao đổi nhiệt ròng.","memoryTipVi":"T_A = T_B → Q_net = 0."},{"term":"zeroth law of thermodynamics","termVi":"Nguyên lý thứ không Nhiệt động lực học","ipa":"/ˈzɪə.rəʊθ lɔː/","definition":"states that if two objects are in thermal equilibrium, and a third object is in thermal equilibrium with one of those objects, it is also in thermal equilibrium with the other object","definitionVi":"Nếu vật A cân bằng nhiệt với C và B cân bằng nhiệt với C thì A và B cũng cân bằng nhiệt với nhau (cơ sở của nhiệt kế).","memoryTipVi":"Tính chất bắc cầu của nhiệt độ."}],"assessments":[{"uid":"hsphys.ch12.sec01.q002","sourceId":"fs-id1167066766808","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"What is the zeroth law of thermodynamics?","images":[],"choices":[{"label":"a","text":"Energy can neither be created nor destroyed in a chemical reaction."},{"label":"b","text":"If two systems, A and B, are in thermal equilibrium with each other, and B is in thermal equilibrium with a third system, C, then A is also in thermal equilibrium with C."},{"label":"c","text":"Entropy of any isolated system not in thermal equilibrium always increases."},{"label":"d","text":"Entropy of a system approaches a constant value as temperature approaches absolute zero."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec01.q003","sourceId":"fs-id1167063596454","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"When are two bodies in thermal equilibrium?","images":[],"choices":[{"label":"a","text":"When they are in thermal contact and are at different pressures"},{"label":"b","text":"When they are not in thermal contact but are at the same pressure"},{"label":"c","text":"When they are not in thermal contact but are at different temperatures"},{"label":"d","text":"When they are in thermal contact and are at the same temperature"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec01.q004","sourceId":"eip-id1166847269008","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"What is thermal contact?","images":[],"choices":[{"label":"a","text":"Two objects are said to be in thermal contact when they are in contact with each other in such a way that the transfer of energy by heat can occur between them."},{"label":"b","text":"Two objects are said to be in thermal contact when they are in contact with each other in such a way that the transfer of energy by mass can occur between them."},{"label":"c","text":"Two objects are said to be in thermal contact when they neither lose nor gain energy by heat. There is no transfer of energy between them."},{"label":"d","text":"Two objects are said to be in thermal contact when they only gain energy by heat. There is transfer of energy between them."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec01.q005","sourceId":"eip-id1166850143864","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"To which mathematical property is the zeroth law of thermodynamics similar?","images":[],"choices":[{"label":"a","text":"Associative property"},{"label":"b","text":"Commutative property"},{"label":"c","text":"Distributive property"},{"label":"d","text":"Transitive property"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec01.q006","sourceId":"fs-id1167067218019","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"What are the necessary conditions for energy transfer by heat to occur between two bodies through the process of conduction?","images":[],"choices":[{"label":"a","text":"They should be at the same temperature, and they should be in thermal contact."},{"label":"b","text":"They should be at the same temperature, and they should not be in thermal contact."},{"label":"c","text":"They should be at different temperatures, and they should be in thermal contact."},{"label":"d","text":"They should be at different temperatures, and they should not be in thermal contact."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec01.q007","sourceId":"eip-id1166849882852","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"Oil is heated in a pan on a hot plate. The pan is in thermal equilibrium with the hot plate and also with the oil. The temperature of the hot plate is 150 °C . What is the temperature of the oil?","images":[],"choices":[{"label":"a","text":"160 °C"},{"label":"b","text":"150 °C"},{"label":"c","text":"140 °C"},{"label":"d","text":"130 °C"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec01.q009","sourceId":"eip-id1166847361075","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"Name any two industries in which the principles of thermodynamics are used.","images":[],"choices":[{"label":"a","text":"aerospace and information technology (IT) industries"},{"label":"b","text":"industrial manufacturing and aerospace"},{"label":"c","text":"mining and textile industries"},{"label":"d","text":"mining and agriculture industries"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec01.q010","sourceId":"fs-id1167067231417","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"What does green energy development entail?","images":[],"choices":[{"label":"a","text":"Green energy involves finding new ways to harness clean and renewable alternative energy sources."},{"label":"b","text":"Green energy involves finding new ways to conserve alternative energy sources."},{"label":"c","text":"Green energy involves decreasing the efficiency of nonrenewable energy resources."},{"label":"d","text":"Green energy involves finding new ways to harness nonrenewable energy resources."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec01.q011","sourceId":"fs-id1167063710476","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Why are the sun and Earth not in thermal equilibrium?","images":[],"choices":[{"label":"a","text":"The mass of the sun is much greater than the mass of Earth."},{"label":"b","text":"There is a vast amount of empty space between the sun and Earth."},{"label":"c","text":"The diameter of the sun is much greater than the diameter of Earth."},{"label":"d","text":"The sun is in thermal contact with Earth."}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":1,"keyEquationCount":0,"subsectionCount":0,"workedExampleCount":0,"snapLabCount":0,"glossaryCount":2,"assessmentCount":9}},{"uid":"hsphys.ch12.sec02","moduleId":"m54305","number":"12.2","slug":"first-law-of-thermodynamics-thermal-energy-and-work","title":"First law of Thermodynamics: Thermal Energy and Work","isIntroduction":false,"learningObjectives":["Describe how pressure, volume, and temperature relate to one another and to work, based on the ideal gas law","Describe pressure–volume work","Describe the first law of thermodynamics verbally and mathematically","Solve problems involving the first law of thermodynamics"],"bilingualGuide":{"notebookSummaryVi":"Nguyên lý I Nhiệt động lực học (ΔU = Q - W) và Phương trình khí lý tưởng (PV = Nk_B T = nRT).","wordProblemCues":[{"phraseEn":"work done BY the system","meaningVi":"Công DO hệ khí thực hiện khi giãn nở (W = PΔV)","mathNotation":"ΔU = Q - W"}],"commonTrapsVi":["⚠️ False Friend Quy ước dấu Việt–Mỹ: Sách Mỹ viết ΔU = Q - W (W là công hệ SINH RA); SGK Việt Nam viết ΔU = Q + A (A là công hệ NHẬN VÀO). Bản chất hoàn toàn giống nhau!"]},"keyEquations":[{"name":"ideal gas law","formula":"\\(PV = NkT\\)"},{"name":"first law of thermodynamics","formula":"\\(\\Delta U = Q - W\\)"},{"name":"pressure","formula":"\\(P = \\frac{F}{A}\\)"},{"name":"pressure–volume work","formula":"\\(W = P\\Delta V\\)"}],"subsections":[{"uid":"hsphys.ch12.sec02.sub01","title":"Pressure, Volume, Temperature, and the Ideal Gas Law","summaryVi":"Nguyên lý I Nhiệt động lực học (ΔU = Q - W) và Phương trình khí lý tưởng (PV = Nk_B T = nRT). Thuật ngữ trọng tâm trong mục này: Boltzmann constant (Hằng số Boltzmann (k_B)), first law of thermodynamics (Nguyên lý I Nhiệt động lực học), ideal gas law (Phương trình trạng thái khí lý tưởng), pressure (Áp suất (P)).","paragraphs":["Before covering the first law of thermodynamics, it is first important to understand the relationship between pressure , volume, and temperature. Pressure, P , is defined as","where F is a force applied to an area, A , that is perpendicular to the force.","Depending on the area over which it is exerted, a given force can have a significantly different effect, as shown in Figure 12.2.","The SI unit for pressure is the pascal , where \\(\\text{1 Pa} = {\\text{1 N/m}}^{\\text{2}}.\\)","Pressure is defined for all states of matter but is particularly important when discussing fluids (such as air). You have probably heard the word pressure being used in relation to blood (high or low blood pressure) and in relation to the weather (high- and low-pressure weather systems). These are only two of many examples of pressures in fluids.","The relationship between the pressure, volume, and temperature for an ideal gas is given by the ideal gas law . A gas is considered ideal at low pressure and fairly high temperature, and forces between its component particles can be ignored. The ideal gas law states that","where P is the pressure of a gas, V is the volume it occupies, N is the number of particles (atoms or molecules) in the gas, and T is its absolute temperature. The constant k is called the Boltzmann constant and has the value \\(k = 1.38 \\times {10}^{-23}\\text{J/K}\\text{,}\\) For the purposes of this chapter, we will not go into calculations using the ideal gas law. Instead, it is important for us to notice from the equation that the following are true for a given mass of gas:","This last point describes thermal expansion —the change in size or volume of a given mass with temperature. What is the underlying cause of thermal expansion? An increase in temperature means that there’s an increase in the kinetic energy of the individual atoms. Gases are especially affected by thermal expansion, although liquids expand to a lesser extent with similar increases in temperature, and even solids have minor expansions at higher temperatures. This is why railroad tracks and bridges have expansion joints that allow them to freely expand and contract with temperature changes.","To get some idea of how pressure, temperature, and volume of a gas are related to one another, consider what happens when you pump air into a deflated tire. The tire’s volume first increases in direct proportion to the amount of air injected, without much increase in the tire pressure. Once the tire has expanded to nearly its full size, the walls limit volume expansion. If you continue to pump air into tire (which now has a nearly constant volume), the pressure increases with increasing temperature (see Figure 12.2)."],"figures":[{"sourceId":"fs-id1167065872907","filename":"CNX_HSPhysics_12_02_shot.jpg","relativePath":"media/CNX_HSPhysics_12_02_shot.jpg","alt":"In part (a), a finger pokes a man’s arm. In part (b), a needle pokes a man’s arm with the same force but over a smaller area, resulting in greater pressure."},{"sourceId":"fs-id1167065931330","filename":"CNX_HSPhysics_12_02_tirepressu.jpg","relativePath":"media/CNX_HSPhysics_12_02_tirepressu.jpg","alt":"In part (a), air is added to a tire, measured using a pressure gauge, and the tire increases in volume. In part (b), more air is added but the volume remains the same, resulting in greater pressure as indicated by the gauge. In part (c), the volume remains nearly constant, so that an increase in temperature increases the pressure."}],"tables":[]},{"uid":"hsphys.ch12.sec02.sub02","title":"Pressure–Volume Work","summaryVi":"Nguyên lý I Nhiệt động lực học (ΔU = Q - W) và Phương trình khí lý tưởng (PV = Nk_B T = nRT). Thuật ngữ trọng tâm trong mục này: pressure (Áp suất (P)).","paragraphs":["Pressure–volume work is the work that is done by the compression or expansion of a fluid. Whenever there is a change in volume and external pressure remains constant, pressure–volume work is taking place. During a compression, a decrease in volume increases the internal pressure of a system as work is done on the system. During an expansion (Figure 12.3), an increase in volume decreases the internal pressure of a system as the system does work.","Recall that the formula for work is \\(W = Fd.\\) We can rearrange the definition of pressure, \\(P = \\frac{F}{A},\\) to get an expression for force in terms of pressure.","Substituting this expression for force into the definition of work, we get","Because area multiplied by displacement is the change in volume, \\(W = P\\Delta V\\)\n, the mathematical expression for pressure–volume work is","Just as we say that work is force acting over a distance, for fluids, we can say that work is the pressure acting through the change in volume. For pressure–volume work, pressure is analogous to force, and volume is analogous to distance in the traditional definition of work."],"figures":[{"sourceId":"fs-id1167065860198","filename":"CNX_HSPhysics_12_02_Expansion.jpg","relativePath":"media/CNX_HSPhysics_12_02_Expansion.jpg","alt":"A piston in an engine cylinder with cross-sectional area A moves up a distance d as energy is added, causing the volume to expand by Ad."}],"tables":[]},{"uid":"hsphys.ch12.sec02.sub03","title":"The First Law of Thermodynamics","summaryVi":"Nguyên lý I Nhiệt động lực học (ΔU = Q - W) và Phương trình khí lý tưởng (PV = Nk_B T = nRT). Thuật ngữ trọng tâm trong mục này: first law of thermodynamics (Nguyên lý I Nhiệt động lực học), internal energy (Nội năng (U)).","paragraphs":["Heat ( Q ) and work ( W ) are the two ways to add or remove energy from a system. The processes are very different. Heat is driven by temperature differences, while work involves a force exerted through a distance. Nevertheless, heat and work can produce identical results. For example, both can cause a temperature increase. Heat transfers energy into a system, such as when the sun warms the air in a bicycle tire and increases the air’s temperature. Similarly, work can be done on the system, as when the bicyclist pumps air into the tire. Once the temperature increase has occurred, it is impossible to tell whether it was caused by heat or work. Heat and work are both energy in transit—neither is stored as such in a system. However, both can change the internal energy, U , of a system.","Internal energy is the sum of the kinetic and potential energies of a system’s atoms and molecules. It can be divided into many subcategories, such as thermal and chemical energy, and depends only on the state of a system (that is, P , V , and T ), not on how the energy enters or leaves the system.","In order to understand the relationship between heat, work, and internal energy, we use the first law of thermodynamics . The first law of thermodynamics applies the conservation of energy principle to systems where heat and work are the methods of transferring energy into and out of the systems. It can also be used to describe how energy transferred by heat is converted and transferred again by work.","The first law of thermodynamics states that the change in internal energy of a closed system equals the net heat transfer into the system minus the net work done by the system. In equation form, the first law of thermodynamics is","Here, \\(\\Delta U\\)\nis the change in internal energy , U , of the system. As shown in Figure 12.2, Q is the net heat transferred into the system —that is, Q is the sum of all heat transfers into and out of the system. W is the net work done by the system —that is, W is the sum of all work done on or by the system. By convention, if Q is positive, then there is a net heat transfer into the system; if W is positive, then there is net work done by the system. So positive Q adds energy to the system by heat, and positive W takes energy from the system by work. Note that if heat transfers more energy into the system than that which is done by work, the difference is stored as internal energy.","It follows also that negative Q indicates that energy is transferred away from the system by heat and so decreases the system’s internal energy, whereas negative W is work done on the system, which increases the internal energy."],"figures":[{"sourceId":"fs-id1167065022930","filename":"CNX_HSPhysics_12_02_FirstTherm.jpg","relativePath":"media/CNX_HSPhysics_12_02_FirstTherm.jpg","alt":"Q is shown adding energy to the system, while W causes energy to leave the system. For the system, the following equations are shown:"}],"tables":[]}],"workedExamples":[{"uid":"hsphys.ch12.sec02.ex01","number":"12.2.1","title":"Calculating Change in Internal Energy","problem":"Suppose 40.00 J of energy is transferred by heat to a system, while the system does 10.00 J of work. Later, heat transfers 25.00 J out of the system, while 4.00 J is done by work on the system. What is the net change in the system’s internal energy?","problemImages":[],"strategy":"You must first calculate the net heat and net work. Then, using the first law of thermodynamics, \\(\\Delta U = Q - W,\\) find the change in internal energy.","solution":"The net heat is the transfer into the system by heat minus the transfer out of the system by heat, or\n\\(Q = \\text{40}\\text{.00 J} - \\text{25}\\text{.00 J} = \\text{15}\\text{.00 J.}\\)\nThe total work is the work done by the system minus the work done on the system, or\n\\(W = \\text{10}\\text{.00 J} - \\text{4}\\text{.00 J} = \\text{6}\\text{.00 J.}\\) The change in internal energy is given by the first law of thermodynamics.\n\\(\\Delta U = Q - W = \\text{15}\\text{.00 J} - \\text{6}\\text{.00 J} = \\text{9}\\text{.00 J}\\)","solutionImages":[],"solutionTables":[],"discussion":"A different way to solve this problem is to find the change in internal energy for each of the two steps separately and then add the two changes to get the total change in internal energy. This approach would look as follows:\nFor 40.00 J of heat in and 10.00 J of work out, the change in internal energy is\n\\(\\Delta {U}_{1} = {Q}_{1} - {W}_{1} = \\text{40}\\text{.00 J} - \\text{10}\\text{.00 J} = \\text{30}\\text{.00 J.}\\) For 25.00 J of heat out and 4.00 J of work in, the change in internal energy is\n\\(\\Delta {U}_{2} = {Q}_{2} - {W}_{2} = - 25.\\,\\text{00 J} - ( - 4.00\\,\\text{J)} = - 21.\\,\\text{00 J.}\\) The total change is\n\\(\\Delta U = \\Delta {U}_{1} + \\Delta {U}_{2} = 3\\,\\text{0}\\text{.00 J} + ( - 21.\\,\\text{00 J)} = 9.\\,\\text{00 J.}\\) No matter whether you look at the overall process or break it into steps, the change in internal energy is the same."},{"uid":"hsphys.ch12.sec02.ex02","number":"12.2.2","title":"Calculating Change in Internal Energy: The Same Change in U is Produced by Two Different Processes","problem":"What is the change in the internal energy of a system when a total of 150.00 J is transferred by heat from the system and 159.00 J is done by work on the system?","problemImages":[],"strategy":"The net heat and work are already given, so simply use these values in the equation \\(\\Delta U = Q - W.\\)","solution":"Here, the net heat and total work are given directly as \\(Q = - \\text{150}\\text{.00 J and}W = - \\text{159.00 J,}\\) so that\n\\(\\Delta U = Q - W = - 150.\\,\\text{00 J} - ( - 159.\\,\\text{00 J)} = 9.\\,\\text{00 J.}\\)","solutionImages":[],"solutionTables":[],"discussion":"Two different processes produce the same change in a system. (a) A total\nof 15.00 J of heat transfer occurs into the system, while work takes out a total of 6.00 J.\nThe change in internal energy is ΔU = Q – W = 9.00 J. (b) Heat transfer removes\n150.00 J from the system while work puts 159.00 J into it, producing an increase of 9.00\nJ in internal energy. If the system starts out in the same state in (a) and (b), it will end\nup in the same final state in either case—its final state is related to internal energy, not\nhow that energy was acquired.\nA very different process in this second worked example produces the same 9.00 J change in internal energy as in the first worked example. Note that the change in the system in both parts is related to \\(\\Delta U\\) and not to the individual Q ’s or W ’s involved. The system ends up in the same state in both problems. Note that, as usual, in the figure/table above, \\({W}_{\\text{out}}\\)\nis work done by the system, and \\({W}_{\\text{in}}\\)\nis work done on the system."}],"snapLabs":[],"tipsAndFeatures":[{"uid":"hsphys.ch12.sec02.feat01","type":"tip","title":"Tips for Success","text":"Recall that the principle of conservation of energy states that energy cannot be created or destroyed, but it can be altered from one form to another.","images":[]},{"uid":"hsphys.ch12.sec02.feat02","type":"physics-in-action","title":"Biology: Biological Thermodynamics","text":"We often think about thermodynamics as being useful for inventing or testing machinery, such as engines or steam turbines. However, thermodynamics also applies to living systems, such as our own bodies. This forms the basis of the biological thermodynamics (Figure 12.2).\n(a) The first law of thermodynamics applies to metabolism. Heat transferred out of the body (Q) and work done by the body (W) remove internal energy, whereas food intake replaces it. (Food intake may be considered work done on the body.) (b) Plants convert part of the radiant energy in sunlight into stored chemical energy, a process called photosynthesis .\nLife itself depends on the biological transfer of energy. Through photosynthesis, plants absorb solar energy from the sun and use this energy to convert carbon dioxide and water into glucose and oxygen. Photosynthesis takes in one form of energy—light—and converts it into another form—chemical potential energy (glucose and other carbohydrates).\nHuman metabolism is the conversion of food into energy given off by heat, work done by the body’s cells, and stored fat. Metabolism is an interesting example of the first law of thermodynamics in action. Eating increases the internal energy of the body by adding chemical potential energy; this is an unromantic view of a good burrito.\nThe body metabolizes all the food we consume. Basically, metabolism is an oxidation process in which the chemical potential energy of food is released. This implies that food input is in the form of work. Exercise helps you lose weight, because it provides energy transfer from your body by both heat and work and raises your metabolic rate even when you are at rest.\nBiological thermodynamics also involves the study of transductions between cells and living organisms. Transduction is a process where genetic material—DNA—is transferred from one cell to another. This often occurs during a viral infection (e.g., influenza) and is how the virus spreads, namely, by transferring its genetic material to an increasing number of previously healthy cells. Once enough cells become infected, you begin to feel the effects of the virus (flu symptoms—muscle weakness, coughing, and congestion).\nEnergy is transferred along with the genetic material and so obeys the first law of thermodynamics. Energy is transferred—not created or destroyed—in the process. When work is done on a cell or heat transfers energy to a cell, the cell’s internal energy increases. When a cell does work or loses heat, its internal energy decreases. If the amount of work done by a cell is the same as the amount of energy transferred in by heat, or the amount of work performed on a cell matches the amount of energy transferred out by heat, there will be no net change in internal energy.\nBased on what you know about heat transfer and the first law of thermodynamics, do you need to eat more or less to maintain a constant weight in colder weather? Explain why.\nmore; as more energy is lost by the body in colder weather, the need to eat increases so as to maintain a constant weight\nmore; eating more food means accumulating more fat, which will insulate the body from colder weather and will reduce the energy loss\nless; as less energy is lost by the body in colder weather, the need to eat decreases so as to maintain a constant weight\nless; eating less food means accumulating less fat, so less energy will be required to burn the fat, and, as a result, weight will remain constant","images":[{"sourceId":"fs-id1167062979109","filename":"CNX_HSPhysics_12_02_FoodEnergy.jpg","relativePath":"media/CNX_HSPhysics_12_02_FoodEnergy.jpg","alt":"A man takes in energy from food, gives off heat, and does work in part (a). A flower absorbs heat from the Sun and gives off heat in part (b)."}]}],"summaryPoints":["Pressure is the force per unit area over which the force is applied perpendicular to the area.","Thermal expansion is the increase, or decrease, of the size (length, area, or volume) of a body due to a change in temperature.","The ideal gas law relates the pressure and volume of a gas to the number of gas particles (atoms or molecules) and the absolute temperature of the gas.","Heat and work are the two distinct methods of energy transfer.","Heat is energy transferred solely due to a temperature difference.","The first law of thermodynamics is given as \\(\\Delta U = Q - W\\)\n, where \\(\\Delta U\\) is the change in internal energy of a system, Q is the net energy transfer into the system by heat (the sum of all transfers by heat into and out of the system), and W is the net work done by the system (the sum of all energy transfers by work out of or into the system).","Both Q and W represent energy in transit; only \\(\\Delta U\\) represents an independent quantity of energy capable of being stored.","The internal energy U of a system depends only on the state of the system, and not how it reached that state."],"glossary":[{"term":"Boltzmann constant","termVi":"Hằng số Boltzmann (k_B)","ipa":"/ˈbəʊlts.mən/","definition":"constant with the value k = 1.38×10 -23 J/K, which is used in the ideal gas law","definitionVi":"Hằng số liên hệ nhiệt độ với năng lượng phân tử: k_B = 1.38 × 10⁻²³ J/K.","memoryTipVi":"PV = N·k_B·T (N là số phân tử)."},{"term":"first law of thermodynamics","termVi":"Nguyên lý I Nhiệt động lực học","ipa":"/fɜːst lɔː/","definition":"states that the change in internal energy of a system equals the net energy transfer by heat into the system minus the net work done by the system","definitionVi":"Định luật bảo toàn năng lượng cho quá trình nhiệt: ΔU = Q - W (độ biến thiên nội năng = nhiệt lượng nhận vào trừ công hệ thực hiện).","memoryTipVi":"⚠️ Chú ý quy ước dấu công W: trong sách Mỹ W là công DO HỆ THỰC HIỆN (ΔU = Q - W), khác SGK Việt Nam cũ ΔU = A + Q (A là công hệ NHẬN)!"},{"term":"ideal gas law","termVi":"Phương trình trạng thái khí lý tưởng","ipa":"/aɪˈdɪəl ɡæs lɔː/","definition":"physical law that relates the pressure and volume of a gas to the number of gas molecules or atoms, or number of moles of gas, and the absolute temperature of the gas","definitionVi":"PV = nRT = Nk_B T (liên hệ Áp suất P, Thể tích V, Số mol n và Nhiệt độ tuyệt đối T).","memoryTipVi":"Nhiệt độ T BẮT BUỘC phải đổi sang Kelvin (K)!"},{"term":"internal energy","termVi":"Nội năng (U)","ipa":"/ɪnˈtɜː.nəl ˈen.ə.dʒi/","definition":"sum of the kinetic and potential energies of a system’s constituent particles (atoms or molecules)","definitionVi":"Tổng động năng và thế năng của toàn bộ các phân tử bên trong hệ.","memoryTipVi":"Với khí lý tưởng, nội năng U chỉ phụ thuộc vào nhiệt độ tuyệt đối T."},{"term":"pressure","termVi":"Áp suất (P)","ipa":"/ˈpreʃ.ər/","definition":"force per unit area perpendicular to the force, over which the force acts","definitionVi":"Độ lớn áp lực vuông góc trên một đơn vị diện tích: P = F / A (đơn vị SI: Pascal, 1 Pa = 1 N/m²).","memoryTipVi":"1 atm ≈ 1.013 × 10⁵ Pa."}],"assessments":[{"uid":"hsphys.ch12.sec02.q002","sourceId":"fs-id1167065883806","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"What is the SI unit for pressure?","images":[],"choices":[{"label":"a","text":"pascal, or N/m 3"},{"label":"b","text":"coulomb"},{"label":"c","text":"newton"},{"label":"d","text":"pascal, or N/m 2"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec02.q004","sourceId":"fs-id1167065980384","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"When is pressure-volume work said to be done ON a system?","images":[],"choices":[{"label":"a","text":"When there is an increase in both volume and internal pressure."},{"label":"b","text":"When there is a decrease in both volume and internal pressure."},{"label":"c","text":"When there is a decrease in volume and an increase in internal pressure."},{"label":"d","text":"When there is an increase in volume and a decrease in internal pressure."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec02.q010","sourceId":"fs-id1167067227637","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"How does pressure-volume work relate to heat and internal energy of a system?","images":[],"choices":[{"label":"a","text":"The energy added to a system by heat minus the change in the internal energy of that system is equal to the pressure-volume work done by the\nsystem."},{"label":"b","text":"The sum of the energy released by a system by heat and the change in the internal energy of that system is equal to the pressure-volume work done by\nthe system."},{"label":"c","text":"The product of the energy added to a system by heat and the change in the internal energy of that system is equal to the pressure-volume work done\nby the system."},{"label":"d","text":"If the energy added to a system by heat is divided by the change in the internal energy of that system, the quotient is equal to the pressure-volume\nwork done by the system."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec02.q011","sourceId":"fs-id1167067013925","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"On what does internal energy depend?","images":[],"choices":[{"label":"a","text":"The path of energy changes in the system"},{"label":"b","text":"The state of the system"},{"label":"c","text":"The size of the system"},{"label":"d","text":"The shape of the system"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec02.q012","sourceId":"eip-id1166849882581","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"The first law of thermodynamics helps us understand the relationships among which three quantities?","images":[],"choices":[{"label":"a","text":"Heat, work, and internal energy"},{"label":"b","text":"Heat, work, and external energy"},{"label":"c","text":"Heat, work, and enthalpy"},{"label":"d","text":"Heat, work, and entropy"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec02.q016","sourceId":"eip-id1166850235352","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"Air is pumped into a car tire, causing its temperature to increase. In another tire, the temperature increase is due to exposure to the sun. Is it possible to tell what caused the temperature increase in each tire? Explain your answer.","images":[],"choices":[{"label":"a","text":"No, because it is a chemical change, and the cause of that change does not matter; the final state of both systems are the same."},{"label":"b","text":"Although the final state of each system is identical, the source is different in each case."},{"label":"c","text":"No, because the changes in energy for both systems are the same, and the cause of that change does not matter; the state of each system is identical."},{"label":"d","text":"Yes, the changes in the energy for both systems are the same, but the causes of that change are different, so the states of each system are not identical."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec02.q017","sourceId":"eip-id1166850068047","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"How does the transfer of energy from the sun help plants?","images":[],"choices":[{"label":"a","text":"Plants absorb solar energy from the sun and utilize it during the fertilization process."},{"label":"b","text":"Plants absorb solar energy from the sun and utilize it during the process of photosynthesis to turn it into plant matter."},{"label":"c","text":"Plants absorb solar energy from the sun and utilize it to increase the temperature inside them."},{"label":"d","text":"Plants absorb solar energy from the sun and utilize it during the shedding of their leaves and fruits."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec02.q027","sourceId":"fs-id1167064620290","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"If a fixed quantity of an ideal gas is held at a constant volume, which variable relates to pressure, and what is that relation?","images":[],"choices":[{"label":"a","text":"Temperature; inverse proportionality \\((P\\,∝\\frac{\\text{1}}{T})\\)"},{"label":"b","text":"Temperature, direct proportionality to square root \\((P\\,∝\\sqrt{T})\\)"},{"label":"c","text":"Temperature; direct proportionality \\((P\\,∝T)\\)"},{"label":"d","text":"Temperature; direct proportionality to square \\((P\\,∝{\\,T}^{\\text{2}})\\)"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec02.q031","sourceId":"eip-979","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"By convention, if Q is positive, what is the direction in which heat transfers energy with regard to the system?","images":[],"choices":[{"label":"a","text":"The direction of the heat transfer of energy depends on the changes in W , regardless of the sign of Q ."},{"label":"b","text":"The direction of Q cannot be determined from just the sign of Q ."},{"label":"c","text":"The direction of net heat transfer of energy will be out of the system."},{"label":"d","text":"The direction of net heat transfer of energy will be into the system."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec02.q036","sourceId":"fs-id1167063801287","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"Under which conditions will the work done by the gas in a system increase?","images":[],"choices":[{"label":"a","text":"It will increase when a large amount of energy is added to the system, and that energy causes an increase in the gass volume, its pressure, or both."},{"label":"b","text":"It will increase when a large amount of energy is extracted from the system, and that energy causes an increase in the gass volume, its pressure, or both."},{"label":"c","text":"It will increase when a large amount of energy is added to the system, and that energy causes a decrease in the gass volume, its pressure, or both."},{"label":"d","text":"It will increase when a large amount of energy is extracted from the system, and that energy causes a decrease in the gass volume, its pressure, or both."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec02.q037","sourceId":"fs-id1167066956169","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"How does energy transfer by heat aid in body metabolism?","images":[],"choices":[{"label":"a","text":"The energy is given to the body through the work done by the body ( W ) and through the intake of food, which may also be considered as the work done on the body. The transfer of energy out of the body is by heat (- Q ) ."},{"label":"b","text":"The energy given to the body is by the intake of food, which may also be considered as the work done on the body. The transfer of energy out of the body is by heat (- Q ) and the work done by the body ( W ) ."},{"label":"c","text":"The energy given to the body is by the transfer of energy by heat ( Q ) into the body, which may also be considered as the work done on the body. The transfer of energy out of the body is the work done by the body ( W ) ."},{"label":"d","text":"The energy given to the body is by the transfer of energy by heat ( Q ) inside the body. The transfer of energy out of the body is by the intake of food and the work done by the body ( W ) ."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec02.q038","sourceId":"fs-id1167067214840","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"Two distinct systems have the same amount of stored internal energy. Five hundred joules are added by heat to the first system, and 300 J are added by heat to the second system. What will be the change in internal energy of the first system if it does 200 J of work? How much work will the second system have to do in order to have the same internal energy?","images":[],"choices":[{"label":"a","text":"700 J; 0 J"},{"label":"b","text":"300 J; 300 J"},{"label":"c","text":"700 J; 300 J"},{"label":"d","text":"300 J; 0 J"}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":4,"keyEquationCount":4,"subsectionCount":3,"workedExampleCount":2,"snapLabCount":0,"glossaryCount":5,"assessmentCount":12}},{"uid":"hsphys.ch12.sec03","moduleId":"m54306","number":"12.3","slug":"second-law-of-thermodynamics-entropy","title":"Second Law of Thermodynamics: Entropy","isIntroduction":false,"learningObjectives":["Describe entropy","Describe the second law of thermodynamics","Solve problems involving the second law of thermodynamics"],"bilingualGuide":{"notebookSummaryVi":"Nguyên lý II Nhiệt động lực học và khái niệm Entropy (ΔS = Q/T — độ hỗn loạn của hệ cô lập luôn tăng).","wordProblemCues":[{"phraseEn":"change in entropy","meaningVi":"Độ biến thiên Entropy","mathNotation":"ΔS = Q / T"}],"commonTrapsVi":["Trong công thức ΔS = Q / T, nhiệt độ T BẮT BUỘC phải dùng đơn vị KELVIN (K)!"]},"keyEquations":[{"name":"change in entropy","formula":"\\(\\Delta S = \\frac{Q}{T}\\)"}],"subsections":[{"uid":"hsphys.ch12.sec03.sub01","title":"Entropy","summaryVi":"Nguyên lý II Nhiệt động lực học và khái niệm Entropy (ΔS = Q/T — độ hỗn loạn của hệ cô lập luôn tăng). Thuật ngữ trọng tâm trong mục này: entropy (Entropi (S — Thước đo độ hỗn loạn)), second law of thermodynamics (Nguyên lý II Nhiệt động lực học).","paragraphs":["Recall from the chapter introduction that it is not even theoretically possible for engines to be 100 percent efficient. This phenomenon is explained by the second law of thermodynamics , which relies on a concept known as entropy . Entropy is a measure of the disorder of a system. Entropy also describes how much energy is not available to do work. The more disordered a system and higher the entropy, the less of a system's energy is available to do work.","Although all forms of energy can be used to do work, it is not possible to use the entire available energy for work. Consequently, not all energy transferred by heat can be converted into work, and some of it is lost in the form of waste heat—that is, heat that does not go toward doing work. The unavailability of energy is important in thermodynamics; in fact, the field originated from efforts to convert heat to work, as is done by engines.","The equation for the change in entropy, \\(\\Delta S\\), is","where Q is the heat that transfers energy during a process, and T is the absolute temperature at which the process takes place.","Q is positive for energy transferred into the system by heat and negative for energy transferred out of the system by heat. In SI, entropy is expressed in units of joules per kelvin (J/K). If temperature changes during the process, then it is usually a good approximation (for small changes in temperature) to take T to be the average temperature in order to avoid trickier math (calculus)."],"figures":[],"tables":[]},{"uid":"hsphys.ch12.sec03.sub02","title":"Second Law of Thermodynamics","summaryVi":"Nguyên lý II Nhiệt động lực học và khái niệm Entropy (ΔS = Q/T — độ hỗn loạn của hệ cô lập luôn tăng). Thuật ngữ trọng tâm trong mục này: entropy (Entropi (S — Thước đo độ hỗn loạn)), second law of thermodynamics (Nguyên lý II Nhiệt động lực học).","paragraphs":["Have you ever played the card game 52 pickup? If so, you have been on the receiving end of a practical joke and, in the process, learned a valuable lesson about the nature of the universe as described by the second law of thermodynamics. In the game of 52 pickup, the prankster tosses an entire deck of playing cards onto the floor, and you get to pick them up. In the process of picking up the cards, you may have noticed that the amount of work required to restore the cards to an orderly state in the deck is much greater than the amount of work required to toss the cards and create the disorder.","The second law of thermodynamics states that the total entropy of a system either increases or remains constant in any spontaneous process; it never decreases. An important implication of this law is that heat transfers energy spontaneously from higher- to lower-temperature objects, but never spontaneously in the reverse direction. This is because entropy increases for heat transfer of energy from hot to cold (Figure 12.3). Because the change in entropy is Q / T , there is a larger change in \\(\\Delta S\\) at lower temperatures (smaller T ). The decrease in entropy of the hot (larger T ) object is therefore less than the increase in entropy of the cold (smaller T ) object, producing an overall increase in entropy for the system.","Another way of thinking about this is that it is impossible for any process to have, as its sole result, heat transferring energy from a cooler to a hotter object. Heat cannot transfer energy spontaneously from colder to hotter, because the entropy of the overall system would decrease.","Suppose we mix equal masses of water that are originally at two different temperatures, say 20 .0 °C\nand 40 .0 °C . The result will be water at an intermediate temperature of 30 .0 °C . Three outcomes have resulted: entropy has increased, some energy has become unavailable to do work, and the system has become less orderly. Let us think about each of these results.","First, why has entropy increased? Mixing the two bodies of water has the same effect as the heat transfer of energy from the higher-temperature substance to the lower-temperature substance. The mixing decreases the entropy of the hotter water but increases the entropy of the colder water by a greater amount, producing an overall increase in entropy.","Second, once the two masses of water are mixed, there is no more temperature difference left to drive energy transfer by heat and therefore to do work. The energy is still in the water, but it is now unavailable to do work.","Third, the mixture is less orderly, or to use another term, less structured. Rather than having two masses at different temperatures and with different distributions of molecular speeds, we now have a single mass with a broad distribution of molecular speeds, the average of which yields an intermediate temperature.","These three results—entropy, unavailability of energy, and disorder—not only are related but are, in fact, essentially equivalent. Heat transfer of energy from hot to cold is related to the tendency in nature for systems to become disordered and for less energy to be available for use as work.","Based on this law, what cannot happen? A cold object in contact with a hot one never spontaneously transfers energy by heat to the hot object, getting colder while the hot object gets hotter. Nor does a hot, stationary automobile ever spontaneously cool off and start moving.","Another example is the expansion of a puff of gas introduced into one corner of a vacuum chamber. The gas expands to fill the chamber, but it never regroups on its own in the corner. The random motion of the gas molecules could take them all back to the corner, but this is never observed to happen (Figure 12.3).","We've explained that heat never transfers energy spontaneously from a colder to a hotter object. The key word here is spontaneously . If we do work on a system, it is possible to transfer energy by heat from a colder to hotter object. We'll learn more about this in the next section, covering refrigerators as one of the applications of the laws of thermodynamics.","Sometimes people misunderstand the second law of thermodynamics, thinking that based on this law, it is impossible for entropy to decrease at any particular location. But, it actually is possible for the entropy of one part of the universe to decrease, as long as the total change in entropy of the universe increases. In equation form, we can write this as","\\(\\Delta {S}_{\\text{tot}} = \\Delta {S}_{\\text{syst}} + \\Delta {S}_{\\text{envir}} \\gt 0\\text{.}\\)","Based on this equation, we see that \\(\\Delta {S}_{\\text{syst}}\\) can be negative as long as \\(\\Delta {S}_{\\text{envir}}\\) is positive and greater in magnitude.","How is it possible for the entropy of a system to decrease? Energy transfer is necessary. If you pick up marbles that are scattered about the room and put them into a cup, your work has decreased the entropy of that system. If you gather iron ore from the ground and convert it into steel and build a bridge, your work has decreased the entropy of that system. Energy coming from the sun can decrease the entropy of local systems on Earth—that is, \\(\\Delta {S}_{\\text{syst}}\\) is negative. But the overall entropy of the rest of the universe increases by a greater amount—that is, \\(\\Delta {S}_{\\text{envir}}\\) is positive and greater in magnitude. In the case of the iron ore, although you made the system of the bridge and steel more structured, you did so at the expense of the universe. Altogether, the entropy of the universe is increased by the disorder created by digging up the ore and converting it to steel. Therefore,","and the second law of thermodynamics is not violated.","Every time a plant stores some solar energy in the form of chemical potential energy, or an updraft of warm air lifts a soaring bird, Earth experiences local decreases in entropy as it uses part of the energy transfer from the sun into deep space to do work. There is a large total increase in entropy resulting from this massive energy transfer. A small part of this energy transfer by heat is stored in structured systems on Earth, resulting in much smaller, local decreases in entropy."],"figures":[{"sourceId":"fs-id1167066039727","filename":"CNX_HSPhysics_12_03_Drink.jpg","relativePath":"media/CNX_HSPhysics_12_03_Drink.jpg","alt":"Ice water in a glass with a straw and lemon wedge."},{"sourceId":"fs-id1167062971494","filename":"CNX_HSPhysics_12_03_Entropy.jpg","relativePath":"media/CNX_HSPhysics_12_03_Entropy.jpg","alt":"In part (a), heat travels from a hotter box to a cooler box. In part (b), a car brakes and releases some heat to the environment. In part (c), a spray bottle releases a puff of air into a vacuum, where the molecules become evenly distributed."}],"tables":[]},{"uid":"hsphys.ch12.sec03.sub03","title":"Solving Problems Involving the Second Law of Thermodynamics","summaryVi":"Nguyên lý II Nhiệt động lực học và khái niệm Entropy (ΔS = Q/T — độ hỗn loạn của hệ cô lập luôn tăng). Thuật ngữ trọng tâm trong mục này: entropy (Entropi (S — Thước đo độ hỗn loạn)).","paragraphs":["Entropy is related not only to the unavailability of energy to do work; it is also a measure of disorder. For example, in the case of a melting block of ice, a highly structured and orderly system of water molecules changes into a disorderly liquid, in which molecules have no fixed positions (Figure 12.3). There is a large increase in entropy for this process, as we'll see in the following worked example."],"figures":[{"sourceId":"fs-id1167064934071","filename":"CNX_HSPhysics_12_03_IceGator.jpg","relativePath":"media/CNX_HSPhysics_12_03_IceGator.jpg","alt":"Ice frozen in the shape of an alligator pokes through the surface of the water."}],"tables":[]}],"workedExamples":[{"uid":"hsphys.ch12.sec03.ex01","number":"12.3.1","title":"Entropy Associated with Disorder","problem":"Find the increase in entropy of 1.00 kg of ice that is originally at 0 °C\nand melts to form water at 0 °C .","problemImages":[],"strategy":"The change in entropy can be calculated from the definition of \\(\\Delta S\\) once we find the energy, Q , needed to melt the ice.","solution":"The change in entropy is defined as\n\\(\\Delta S = \\frac{Q}{T}\\text{.}\\)\nHere, Q is the heat necessary to melt 1.00 kg of ice and is given by\n\\(Q = m{L}_{f}\\text{,}\\)\nwhere m is the mass and \\({L}_{f}\\) is the latent heat of fusion. \\({L}_{f} = \\text{334 kJ/kg}\\) for water, so\n\\(Q = (\\text{1}\\text{.00 kg})(\\text{334 kJ/kg}) = 3.34 \\times {10}^{5}\\text{J.}\\)\nBecause Q is the amount of energy heat adds to the ice, its value is positive, and T is the melting temperature of ice, \\(T = \\text{273 K}\\) So the change in entropy is\n\\(\\Delta S = \\frac{Q}{T} = \\frac{3.34 \\times {10}^{5}\\text{J}}{\\text{273 K}} = 1.22 \\times {10}^{3}\\text{J/K.}\\)","solutionImages":[],"solutionTables":[],"discussion":"When ice melts, it becomes more disordered and less structured. The\nsystematic arrangement of molecules in a crystal structure is replaced by a more\nrandom and less orderly movement of molecules without fixed locations or orientations.\nIts  entropy increases because heat transfer occurs into it. Entropy is a measure of\ndisorder.\nThe change in entropy is positive, because heat transfers energy into the ice to cause the phase change. This is a significant increase in entropy, because it takes place at a relatively low temperature. It is accompanied by an increase in the disorder of the water molecules."}],"snapLabs":[],"tipsAndFeatures":[{"uid":"hsphys.ch12.sec03.feat01","type":"tip","title":"Tips for Success","text":"Absolute temperature is the temperature measured in Kelvins. The Kelvin scale is an absolute temperature scale that is measured in terms of the number of degrees above absolute zero. All temperatures are therefore positive. Using temperatures from another, nonabsolute scale, such as Fahrenheit or Celsius, will give the wrong answer.","images":[]}],"summaryPoints":["Entropy is a measure of a system's disorder: the greater the disorder, the larger the entropy.","Entropy is also the reduced availability of energy to do work.","The second law of thermodynamics states that, for any spontaneous process, the total entropy of a system either increases or remains constant; it never decreases.","Heat transfers energy spontaneously from higher- to lower-temperature bodies, but never spontaneously in the reverse direction."],"glossary":[{"term":"entropy","termVi":"Entropi (S — Thước đo độ hỗn loạn)","ipa":"/ˈen.trə.pi/","definition":"measurement of a system's disorder and how much energy is not available to do work in a system","definitionVi":"Đại lượng đặc trưng cho mức độ hỗn loạn (mất trật tự) của hệ nhiệt động: ΔS = Q / T.","memoryTipVi":"Trong hệ cô lập tự nhiên, Entropy luôn TĂNG hoặc giữ nguyên (ΔS ≥ 0)."},{"term":"second law of thermodynamics","termVi":"Nguyên lý II Nhiệt động lực học","ipa":"/ˈsek.ənd lɔː/","definition":"states that the total entropy of a system either increases or remains constant in any spontaneous process; it never decreases","definitionVi":"Nhiệt tự truyền từ vật nóng sang vật lạnh, không thể chế tạo động cơ nhiệt đạt hiệu suất 100%, và tổng Entropy vũ trụ không bao giờ giảm.","memoryTipVi":"Quy định \"mũi tên thời gian\" trong tự nhiên."}],"assessments":[{"uid":"hsphys.ch12.sec03.q001","sourceId":"fs-id1167065768478","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"What is entropy?","images":[],"choices":[{"label":"a","text":"Entropy is a measure of the potential energy of a system."},{"label":"b","text":"Entropy is a measure of the net work done by a system."},{"label":"c","text":"Entropy is a measure of the disorder of a system."},{"label":"d","text":"Entropy is a measure of the heat transfer of energy into a system."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec03.q002","sourceId":"fs-id1167065864894","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"Which forms of energy can be used to do work?","images":[],"choices":[{"label":"a","text":"Only work is able to do work."},{"label":"b","text":"Only heat is able to do work."},{"label":"c","text":"Only internal energy is able to do work."},{"label":"d","text":"Heat, work, and internal energy are all able to do work."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec03.q004","sourceId":"fs-id1167065846557","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"For heat transferring energy from a high to a low temperature, what usually happens to the entropy of the whole system?","images":[],"choices":[{"label":"a","text":"It decreases."},{"label":"b","text":"It must remain constant."},{"label":"c","text":"The entropy of the system cannot be predicted without specific values for the temperatures."},{"label":"d","text":"It increases."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec03.q007","sourceId":"fs-id1167064875350","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"Air freshener is sprayed from a bottle. The molecules spread throughout the room and cannot make their way back into the bottle. Why is this the case?","images":[],"choices":[{"label":"a","text":"The entropy of the molecules increases."},{"label":"b","text":"The entropy of the molecules decreases."},{"label":"c","text":"The heat content ( enthalpy , or total energy available for heat) of the molecules increases."},{"label":"d","text":"The heat content ( enthalpy , or total energy available for heat) of the molecules decreases."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec03.q008","sourceId":"fs-id1167067075836","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"Give an example of entropy as experienced in everyday life.","images":[],"choices":[{"label":"a","text":"rotation of Earth"},{"label":"b","text":"formation of a solar eclipse"},{"label":"c","text":"filling a car tire with air"},{"label":"d","text":"motion of a pendulum bob"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec03.q009","sourceId":"fs-id1167064981393","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"If an engine were constructed to perform such that there would be no losses due to friction, what would be its efficiency?","images":[],"choices":[{"label":"a","text":"It would be 0 percent."},{"label":"b","text":"It would be less than 100 percent."},{"label":"c","text":"It would be 100 percent."},{"label":"d","text":"It would be greater than 100 percent."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec03.q010","sourceId":"fs-id1167063547306","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"Entropy never decreases in a spontaneous process. Give an example to support this statement.","images":[],"choices":[{"label":"a","text":"The transfer of energy by heat from colder bodies to hotter bodies is a spontaneous process in which the entropy of the system of bodies increases."},{"label":"b","text":"The melting of an ice cube placed in a room causes an increase in the entropy of the room."},{"label":"c","text":"The dissolution of salt in water is a spontaneous process in which the entropy of the system increases."},{"label":"d","text":"A plant uses energy from the sun and converts it into sugar molecules by the process of photosynthesis."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec03.q016","sourceId":"eip-id1166847411233","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"Why does entropy increase during a spontaneous process?","images":[],"choices":[{"label":"a","text":"Entropy increases because energy always transfers spontaneously from a dispersed state to a concentrated state."},{"label":"b","text":"Entropy increases because energy always transfers spontaneously from a concentrated state to a dispersed state."},{"label":"c","text":"Entropy increases because pressure always increases spontaneously."},{"label":"d","text":"Entropy increases because temperature of any system always increases spontaneously."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec03.q017","sourceId":"eip-id1166849875617","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"A system consists of ice melting in a glass of water. What happens to the entropy of this system?","images":[],"choices":[{"label":"a","text":"The entropy of the ice decreases, while the entropy of the water cannot be predicted without more specific information."},{"label":"b","text":"The entropy of the system remains constant."},{"label":"c","text":"The entropy of the system decreases."},{"label":"d","text":"The entropy of the system increases."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec03.q019","sourceId":"fs-id1167063563117","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Which one of the following types of energy of the molecules in a solid contributes to its thermal energy?","images":[],"choices":[{"label":"a","text":"electric potential energy"},{"label":"b","text":"gravitational potential energy"},{"label":"c","text":"translational kinetic energy"},{"label":"d","text":"vibrational kinetic energy"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec03.q022","sourceId":"fs-id1167067026492","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"What is the change in entropy caused by melting 5.00 kg of ice at 0 °C ?","images":[],"choices":[{"label":"a","text":"0 J/K"},{"label":"b","text":"6.11×10 3 J/K"},{"label":"c","text":"6.11×10 4 J/K"},{"label":"d","text":"∞J/K"}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":3,"keyEquationCount":1,"subsectionCount":3,"workedExampleCount":1,"snapLabCount":0,"glossaryCount":2,"assessmentCount":11}},{"uid":"hsphys.ch12.sec04","moduleId":"m54307","number":"12.4","slug":"applications-of-thermodynamics-heat-engines-heat-pumps-and-refrigerators","title":"Applications of Thermodynamics: Heat Engines, Heat Pumps, and Refrigerators","isIntroduction":false,"learningObjectives":["Explain how heat engines, heat pumps, and refrigerators work in terms of the laws of thermodynamics","Describe thermal efficiency","Solve problems involving thermal efficiency"],"bilingualGuide":{"notebookSummaryVi":"Động cơ nhiệt (Heat Engine), Hiệu suất nhiệt (Eff = W/Q_h = 1 - Q_c/Q_h), Tủ lạnh và Bơm nhiệt (Heat Pump).","wordProblemCues":[{"phraseEn":"thermal efficiency","meaningVi":"Hiệu suất động cơ nhiệt","mathNotation":"Eff = W / Q_h"}],"commonTrapsVi":["Không một động cơ nhiệt nào đạt hiệu suất 100% vì luôn phải thải một phần nhiệt Q_c ra nguồn lạnh."]},"keyEquations":[{"name":"thermal efficiency of a heat engine","formula":"\\(Eff = \\frac{W}{{Q}_{\\text{h}}}\\)"},{"name":"work output for a cyclical process","formula":"\\(W = {Q}_{\\text{h}} - {Q}_{\\text{c}}\\)"}],"subsections":[{"uid":"hsphys.ch12.sec04.sub01","title":"Heat Engines, Heat Pumps, and Refrigerators","summaryVi":"Động cơ nhiệt (Heat Engine), Hiệu suất nhiệt (Eff = W/Q_h = 1 - Q_c/Q_h), Tủ lạnh và Bơm nhiệt (Heat Pump). Thuật ngữ trọng tâm trong mục này: cyclical process (Chu trình nhiệt động (Quá trình kín)), heat engine (Động cơ nhiệt), heat pump (Bơm nhiệt / Máy điều hòa).","paragraphs":["In this section, we’ll explore how heat engines, heat pumps, and refrigerators operate in terms of the laws of thermodynamics.","One of the most important things we can do with heat is to use it to do work for us. A heat engine does exactly this—it makes use of the properties of thermodynamics to transform heat into work. Gasoline and diesel engines, jet engines, and steam turbines that generate electricity are all examples of heat engines.","Figure 12.4 illustrates one of the ways in which heat transfers energy to do work. Fuel combustion releases chemical energy that heat transfers throughout the gas in a cylinder. This increases the gas temperature, which in turn increases the pressure of the gas and, therefore, the force it exerts on a movable piston. The gas does work on the outside world, as this force moves the piston through some distance. Thus, heat transfer of energy to the gas in the cylinder results in work being done.","To repeat this process, the piston needs to be returned to its starting point. Heat now transfers energy from the gas to the surroundings, so that the gas’s pressure decreases, and a force is exerted by the surroundings to push the piston back through some distance.","A cyclical process brings a system, such as the gas in a cylinder, back to its original state at the end of every cycle. All heat engines use cyclical processes.","Heat engines do work by using part of the energy transferred by heat from some source. As shown in Figure 12.4, heat transfers energy, \\({Q}_{\\text{h}}\\), from the high-temperature object (or hot reservoir), whereas heat transfers unused energy, \\({Q}_{\\text{c}}\\), into the low-temperature object (or cold reservoir), and the work done by the engine is W . In physics, a reservoir is defined as an infinitely large mass that can take in or put out an unlimited amount of heat, depending upon the needs of the system. The temperature of the hot reservoir is \\({T}_{\\text{h}}\\text{,}\\) and the temperature of the cold reservoir is \\({T}_{\\text{c}}\\) .","As noted, a cyclical process brings the system back to its original condition at the end of every cycle. Such a system’s internal energy, U , is the same at the beginning and end of every cycle—that is, \\(\\Delta U = 0\\)\n. The first law of thermodynamics states that \\(\\Delta U = Q - W\\text{,}\\) where Q is the net heat transfer during the cycle, and W is the net work done by the system. The net heat transfer is the energy transferred in by heat from the hot reservoir minus the amount that is transferred out to the cold reservoir ( \\(Q = {Q}_{\\text{h}} - {Q}_{\\text{c}}\\) ). Because there is no change in internal energy for a complete cycle ( \\(\\Delta U = 0\\)\n), we have","so that","Therefore, the net work done by the system equals the net heat into the system, or","for a cyclical process.","Because the hot reservoir is heated externally, which is an energy-intensive process, it is important that the work be done as efficiently as possible. In fact, we want W to equal \\({Q}_{\\text{h}}\\), and for there to be no heat to the environment (that is, \\({Q}_{\\text{c}} = 0\\) ). Unfortunately, this is impossible. According to the second law of thermodynamics, heat engines cannot have perfect conversion of heat into work. Recall that entropy is a measure of the disorder of a system, which is also how much energy is unavailable to do work. The second law of thermodynamics requires that the total entropy of a system either increases or remains constant in any process. Therefore, there is a minimum amount of \\({Q}_{\\text{h}}\\) that cannot be used for work. The amount of heat rejected to the cold reservoir, \\({Q}_{\\text{c}}\\text{,}\\) depends upon the efficiency of the heat engine. The smaller the increase in entropy, \\(\\Delta S\\)\n, the smaller the value of \\({Q}_{\\text{c}}\\), and the more heat energy is available to do work.","Heat pumps , air conditioners, and refrigerators utilize heat transfer of energy from low to high temperatures, which is the opposite of what heat engines do. Heat transfers energy \\({Q}_{\\text{c}}\\) from a cold reservoir and delivers energy \\({Q}_{\\text{h}}\\) into a hot one. This requires work input, W , which produces a transfer of energy by heat. Therefore, the total heat transfer to the hot reservoir is","The purpose of a heat pump is to transfer energy by heat to a warm environment, such as a home in the winter. The great advantage of using a heat pump to keep your home warm rather than just burning fuel in a fireplace or furnace is that a heat pump supplies \\({Q}_{\\text{h}} = {Q}_{\\text{c}} + W\\) . Heat \\({Q}_{\\text{c}}\\) comes from the outside air, even at a temperature below freezing, to the indoor space. You only pay for W , and you get an additional heat transfer of \\({Q}_{\\text{c}}\\) from the outside at no cost. In many cases, at least twice as much energy is transferred to the heated space as is used to run the heat pump. When you burn fuel to keep warm, you pay for all of it. The disadvantage to a heat pump is that the work input (required by the second law of thermodynamics) is sometimes more expensive than simply burning fuel, especially if the work is provided by electrical energy.","The basic components of a heat pump are shown in Figure 12.4. A working fluid, such as a refrigerant, is used. In the outdoor coils (the evaporator), heat \\({Q}_{\\text{c}}\\) enters the working fluid from the cold outdoor air, turning it into a gas.","The electrically driven compressor (work input W ) raises the temperature and pressure of the gas and forces it into the condenser coils that are inside the heated space. Because the temperature of the gas is higher than the temperature inside the room, heat transfers energy to the room, and the gas condenses into a liquid. The liquid then flows back through an expansion (pressure-reducing) valve. The liquid, having been cooled through expansion, returns to the outdoor evaporator coils to resume the cycle.","The quality of a heat pump is judged by how much energy is transferred by heat into the warm space ( \\({Q}_{\\text{h}}\\) ) compared with how much input work ( W ) is required.","Air conditioners and refrigerators are designed to cool substances by transferring energy by heat \\({Q}_{\\text{c}}\\) out of a cool environment to a warmer one, where heat \\({Q}_{\\text{h}}\\) is given up. In the case of a refrigerator, heat is moved out of the inside of the fridge into the surrounding room. For an air conditioner, heat is transferred outdoors from inside a home. Heat pumps are also often used in a reverse setting to cool rooms in the summer.","As with heat pumps, work input is required for heat transfer of energy from cold to hot. The quality of air conditioners and refrigerators is judged by how much energy is removed by heat \\({Q}_{\\text{c}}\\) from a cold environment, compared with how much work, W , is required. So, what is considered the energy benefit in a heat pump, is considered waste heat in a refrigerator."],"figures":[{"sourceId":"fs-id1167066955590","filename":"CNX_HSPhysics_12_04_Cylinder.jpg","relativePath":"media/CNX_HSPhysics_12_04_Cylinder.jpg","alt":"In part (a), heat transfers energy into the gas in a cylinder. In part (b), force pushes the cylinder. In part (c), heat transfers energy out to the environment."},{"sourceId":"fs-id1167063663451","filename":"CNX_HSPhysics_12_04_Reservoirs.jpg","relativePath":"media/CNX_HSPhysics_12_04_Reservoirs.jpg","alt":"In part (a), heat transfers energy from the hot reservoir to the cold reservoir. In part (b), work is produced as this heat transfers energy from the hot to the cold reservoir. The amount of work generated is Qh – Qc."},{"sourceId":"fs-id1167066876234","filename":"CNX_HSPhysics_12_04_HeatPump.jpg","relativePath":"media/CNX_HSPhysics_12_04_HeatPump.jpg","alt":"A complete cycle from evaporator to compressor to condenser to expansion valve is shown. Qc is transferred to the evaporator from outdoors, and the condenser releases Qh indoors."},{"sourceId":"fs-id1167066837088","filename":"CNX_HSPhysics_12_04_Fridge.jpg","relativePath":"media/CNX_HSPhysics_12_04_Fridge.jpg","alt":"In a refrigerator, there is heat transfer (Qc) into the system from a cold reservoir, and heat transfer (Qh) out of the system into a hot reservoir, caused by work (W) done on the system."}],"tables":[]},{"uid":"hsphys.ch12.sec04.sub02","title":"Thermal Efficiency","summaryVi":"Động cơ nhiệt (Heat Engine), Hiệu suất nhiệt (Eff = W/Q_h = 1 - Q_c/Q_h), Tủ lạnh và Bơm nhiệt (Heat Pump). Thuật ngữ trọng tâm trong mục này: heat engine (Động cơ nhiệt), thermal efficiency (Hiệu suất nhiệt (Eff)).","paragraphs":["In the conversion of energy into work, we are always faced with the problem of getting less out than we put in. The problem is that, in all processes, there is some heat \\({Q}_{\\text{c}}\\) that transfers energy to the environment—and usually a very significant amount at that. A way to quantify how efficiently a machine runs is through a quantity called thermal efficiency .","We define thermal efficiency, Eff , to be the ratio of useful energy output to the energy input (or, in other words, the ratio of what we get to what we spend). The efficiency of a heat engine is the output of net work, W , divided by heat-transferred energy, \\({Q}_{\\text{h}}\\), into the engine; that is","\\(Eff = \\frac{W}{{Q}_{\\text{h}}}\\text{.}\\)","An efficiency of 1, or 100 percent, would be possible only if there were no heat to the environment ( \\({Q}_{\\text{c}} = 0\\)\n)."],"figures":[],"tables":[]},{"uid":"hsphys.ch12.sec04.sub03","title":"Performance Task","summaryVi":"Động cơ nhiệt (Heat Engine), Hiệu suất nhiệt (Eff = W/Q_h = 1 - Q_c/Q_h), Tủ lạnh và Bơm nhiệt (Heat Pump).","paragraphs":["You have been tasked to design and construct a thermometer that works on the principle of thermal expansion. There are four materials available for you to test, each of which will find use under different sets of conditions and temperature ranges:"],"figures":[],"tables":[]}],"workedExamples":[{"uid":"hsphys.ch12.sec04.ex01","number":"12.4.1","title":"Daily Work Done by a Coal-Fired Power Station and Its Efficiency","problem":"A coal-fired power station is a huge heat engine. It uses heat to transfer energy from burning coal to do work to turn turbines, which are used then to generate electricity. In a single day, a large coal power station transfers \\(2.50 \\times {10}^{14}\\text{J}\\) by heat from burning coal and transfers \\(1.48 \\times {10}^{14}\\text{J}\\) by heat into the environment. (a) What is the work done by the power station? (b) What is the efficiency of the power station?","problemImages":[],"strategy":"We can use \\(W = {Q}_{\\text{h}} - {Q}_{\\text{c}}\\)\nto find the work output, W , assuming a cyclical process is used in the power station. In this process, water is boiled under pressure to form high-temperature steam, which is used to run steam turbine-generators and then condensed back to water to start the cycle again.","solution":"Work output is given by\n\\(W = {Q}_{\\text{h}} - {Q}_{\\text{c}}\\text{.}\\)\nSubstituting the given values,\n\\(W = 2.50 \\times {10}^{14}\\text{J} - 1.48 \\times {10}^{14}\\text{J} = 1.02 \\times {10}^{14}\\text{J.}\\)","solutionImages":[],"solutionTables":[],"discussion":"The efficiency found is close to the usual value of 42 percent for coal-burning power stations. It means that fully 59.2 percent of the energy is transferred by heat to the environment, which usually results in warming lakes, rivers, or the ocean near the power station and is implicated in a warming planet generally. While the laws of thermodynamics limit the efficiency of such plants—including plants fired by nuclear fuel, oil, and natural gas—the energy transferred by heat to the environment could be, and sometimes is, used for heating homes or for industrial processes."}],"snapLabs":[],"tipsAndFeatures":[{"uid":"hsphys.ch12.sec04.feat01","type":"tip","title":"Tips for Success","text":"All values of heat ( \\({Q}_{\\text{h}}\\) and \\({Q}_{\\text{c}}\\) ) are positive; there is no such thing as negative heat. The direction of heat is indicated by a plus or minus sign. For example, \\({Q}_{\\text{c}}\\) is out of the system, so it is preceded by a minus sign in the equation for net heat.\n\\(Q = {Q}_{\\text{h}} - {Q}_{\\text{c}}\\)","images":[]}],"summaryPoints":["Heat engines use the heat transfer of energy to do work.","Cyclical processes are processes that return to their original state at the end of every cycle.","The thermal efficiency of a heat engine is the ratio of work output divided by the amount of energy input.","The amount of work a heat engine can do is determined by the net heat transfer of energy during a cycle; more waste heat leads to less work output.","Heat pumps draw energy by heat from cold outside air and use it to heat an interior room.","A refrigerator is a type of heat pump; it takes energy from the warm air from the inside compartment and transfers it to warmer exterior air."],"glossary":[{"term":"cyclical process","termVi":"Chu trình nhiệt động (Quá trình kín)","ipa":"/ˈsaɪ.klɪ.kəl/","definition":"process in which a system is brought back to its original state at the end of every cycle","definitionVi":"Quá trình mà hệ quay trở lại đúng trạng thái ban đầu sau một chu kỳ (ΔU = 0 → W = Q_net).","memoryTipVi":"Động cơ ô tô hoạt động theo chu trình lặp đi lặp lại."},{"term":"heat engine","termVi":"Động cơ nhiệt","ipa":"/hiːt ˈen.dʒɪn/","definition":"machine that uses energy transfer by heat to do work","definitionVi":"Thiết bị nhận nhiệt từ nguồn nóng Q_h, sinh công có ích W và nhả phần nhiệt thừa Q_c ra nguồn lạnh.","memoryTipVi":"W = Q_h - Q_c."},{"term":"heat pump","termVi":"Bơm nhiệt / Máy điều hòa","ipa":"/hiːt pʌmp/","definition":"machine that generates the heat transfer of energy from cold to hot","definitionVi":"Thiết bị dùng công cơ học (điện năng) để bơm nhiệt ngược chiều từ nơi lạnh sang nơi nóng.","memoryTipVi":"Tủ lạnh và điều hòa đều hoạt động theo nguyên lý bơm nhiệt."},{"term":"thermal efficiency","termVi":"Hiệu suất nhiệt (Eff)","ipa":"/ˈθɜː.məl ɪˈfɪʃ.ən.si/","definition":"ratio of useful energy output to the energy input","definitionVi":"Tỉ số giữa công sinh ra và nhiệt lượng nhận vào từ nguồn nóng: Eff = W / Q_h = 1 - Q_c / Q_h.","memoryTipVi":"Luôn nhỏ hơn 100% (vì luôn có nhiệt thải Q_c > 0)."}],"assessments":[{"uid":"hsphys.ch12.sec04.q002","sourceId":"fs-id1167067054289","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"Give an example of a heat engine.","images":[],"choices":[{"label":"a","text":"A generator"},{"label":"b","text":"A battery"},{"label":"c","text":"A water pump"},{"label":"d","text":"A car engine"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec04.q006","sourceId":"fs-id1167061322523","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"A heat engine takes in 6.0 kJ from heat and produces waste heat of 4.8 kJ. What is its efficiency?","images":[],"choices":[{"label":"a","text":"25 percent"},{"label":"b","text":"2.50 percent"},{"label":"c","text":"2.00 percent"},{"label":"d","text":"20 percent"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec04.q007","sourceId":"fs-id1167063506662","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"What is the quality by which air conditioners are judged?","images":[],"choices":[{"label":"a","text":"The amount of energy generated by heat from a hot environment, compared with the required work input"},{"label":"b","text":"The amount of energy transferred by heat from a cold environment, compared with the required work input"},{"label":"c","text":"The amount of energy transferred by heat from a hot environment, compared with the required work output"},{"label":"d","text":"The amount of energy transferred by heat from a cold environment, compared with the required work output"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec04.q008","sourceId":"fs-id1167063716308","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"Why is the efficiency of a heat engine never 100 percent?","images":[],"choices":[{"label":"a","text":"Some energy is always gained by heat from the environment."},{"label":"b","text":"Some energy is always lost by heat to the environment."},{"label":"c","text":"Work output is always greater than energy input."},{"label":"d","text":"Work output is infinite for any energy input."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec04.q009","sourceId":"eip-id1166847362299","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"What is a cyclic process?","images":[],"choices":[{"label":"a","text":"A process in which the system returns to its original state at the end of the cycle"},{"label":"b","text":"A process in which the system does not return to its original state at the end of the cycle"},{"label":"c","text":"A process in which the system follows the same path for every cycle"},{"label":"d","text":"A process in which the system follows a different path for every cycle"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec04.q013","sourceId":"fs-id1164566700710","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"What is the advantage of a heat pump as opposed to burning fuel (as in a fireplace) for keeping warm?","images":[],"choices":[{"label":"a","text":"A heat pump supplies energy by heat from the cold, outside air."},{"label":"b","text":"A heat pump supplies energy generated by the work done."},{"label":"c","text":"A heat pump supplies energy by heat from the cold, outside air and also from the energy generated by the work done."},{"label":"d","text":"A heat pump supplies energy not by heat from the cold, outside air, nor from the energy generated by the work done, but from more accessible sources."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec04.q014","sourceId":"fs-id1164564999667","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"What is thermal efficiency of an engine? Can it ever be 100 percent? Why or why not?","images":[],"choices":[{"label":"a","text":"Thermal efficiency is the ratio of the output (work) to the input (heat). It is always 100 percent."},{"label":"b","text":"Thermal efficiency is the ratio of the output (heat) to the input (work). It is always 100 percent."},{"label":"c","text":"Thermal efficiency is the ratio of the output (heat) to the input (work). It is never 100 percent."},{"label":"d","text":"Thermal efficiency is the ratio of the output (work) to the input (heat). It is never 100 percent."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec04.q015","sourceId":"fs-id1164564895336","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"When would 100 percent thermal efficiency be possible?","images":[],"choices":[{"label":"a","text":"When all energy is transferred by heat to the environment"},{"label":"b","text":"When mass transferred to the environment is zero"},{"label":"c","text":"When mass transferred to the environment is at a maximum"},{"label":"d","text":"When no energy is transferred by heat to the environment"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec04.q017","sourceId":"fs-id1167061322523","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"A heat engine takes in 6.0 kJ from heat and produces waste heat of 4.8 kJ. What is its efficiency?","images":[],"choices":[{"label":"a","text":"25 percent"},{"label":"b","text":"2.50 percent"},{"label":"c","text":"2.00 percent"},{"label":"d","text":"20 percent"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec04.q020","sourceId":"fs-id1164564804101","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"A coal power station functions at 40.0 percent efficiency. What is the amount of work it does if it takes in 1.20×10 12 J by heat?","images":[],"choices":[{"label":"a","text":"3×10 10 J"},{"label":"b","text":"4.8×10 11 J"},{"label":"c","text":"3×10 12 J"},{"label":"d","text":"4.8×10 13 J"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec04.q021","sourceId":"fs-id1164562202478","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"A heat engine functions with 70.7 percent thermal efficiency and consumes 12.0 kJ from heat daily. If its efficiency were raised to 75.0 percent, how much energy from heat would be saved daily, while providing the same output?","images":[],"choices":[{"label":"a","text":"-10.8 kJ"},{"label":"b","text":"-1.08 kJ"},{"label":"c","text":"0.7 kJ"},{"label":"d","text":"7 kJ"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec04.q023","sourceId":"fs-id1167063730358","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"Which of these quantities needs to be zero for efficiency to be 100 percent?","images":[],"choices":[{"label":"a","text":"Δ U"},{"label":"b","text":"W"},{"label":"c","text":"Q h"},{"label":"d","text":"Q c"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec04.q024","sourceId":"fs-id1167067090257","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"Which of the following always has the greatest value in a system having 80 percent thermal efficiency?","images":[],"choices":[{"label":"a","text":"Δ U"},{"label":"b","text":"W"},{"label":"c","text":"Q h"},{"label":"d","text":"Q c"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec04.q025","sourceId":"eip-id1166848723677","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"In the equation Q = Q h - Q c , what does the negative sign indicate?","images":[],"choices":[{"label":"a","text":"Heat transfer of energy is always negative."},{"label":"b","text":"Heat transfer can only occur in one direction."},{"label":"c","text":"Heat is directed into the system from the surroundings outside the system."},{"label":"d","text":"Heat is directed out of the system."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec04.q026","sourceId":"eip-id1166848721120","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"What is the purpose of a heat pump?","images":[],"choices":[{"label":"a","text":"A heat pump uses work to transfer energy by heat from a colder environment to a warmer environment."},{"label":"b","text":"A heat pump uses work to transfer energy by heat from a warmer environment to a colder environment."},{"label":"c","text":"A heat pump does work by using heat to convey energy from a colder environment to a warmer environment."},{"label":"d","text":"A heat pump does work by using heat to convey energy from a warmer environment to a colder environment."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec04.q028","sourceId":"fs-id1167066966799","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Which component of an air conditioner converts gas into liquid?","images":[],"choices":[{"label":"a","text":"the condenser"},{"label":"b","text":"the compressor"},{"label":"c","text":"the evaporator"},{"label":"d","text":"the thermostat"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec04.q029","sourceId":"fs-id1167067201514","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"What is one example for which calculating thermal efficiency is of interest?","images":[],"choices":[{"label":"a","text":"A wind turbine"},{"label":"b","text":"An electric pump"},{"label":"c","text":"A bicycle"},{"label":"d","text":"A car engine"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec04.q030","sourceId":"fs-id1167066952806","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"How is the efficiency of a refrigerator or heat pump expressed?","images":[],"choices":[{"label":"a","text":"\\(Eff = W\\sqrt{{Q}_{\\text{c}}}\\)"},{"label":"b","text":"\\(Eff = \\frac{W}{{Q}_{\\text{c}}}\\)"},{"label":"c","text":"\\(Eff = {Q}_{\\text{c}} \\times W\\)"},{"label":"d","text":"\\(Eff = \\frac{{Q}_{\\text{c}}}{W}\\)"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec04.q033","sourceId":"fs-id1167061202574","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"In the equation W = Q h - Q c , if the value of Q c were equal to zero, what would it signify?","images":[],"choices":[{"label":"a","text":"The efficiency of the engine is 75 percent."},{"label":"b","text":"The efficiency of the engine is 25 percent."},{"label":"c","text":"The efficiency of the engine is 0 percent."},{"label":"d","text":"The efficiency of the engine is 100 percent."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch12.sec04.q035","sourceId":"fs-id1167067203188","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"A coal power station transfers 3.0×10 12 J by heat from burning coal and transfers 1.5×10 12 J by heat into the environment. What is the efficiency of the power station?","images":[],"choices":[{"label":"a","text":"0.33"},{"label":"b","text":"0.5"},{"label":"c","text":"0.66"},{"label":"d","text":"1"}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":3,"keyEquationCount":2,"subsectionCount":3,"workedExampleCount":1,"snapLabCount":0,"glossaryCount":4,"assessmentCount":20}}],"summary":{"totalSections":5,"totalKeyEquations":7,"totalWorkedExamples":4,"totalSnapLabs":0,"totalGlossaryTerms":13,"totalAssessments":52,"referencedMediaCount":14},"qualityGate":{"passed":true,"checkedUids":71,"errors":[],"warnings":[]}};
